062a\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0644\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0035","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0035-LMGXZn8.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0035-LMGXZn8.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"26953b1e-5beb-5ecd-8a46-cbfcddfa202d","source_id":"1255","name_en":"barbell decline pullover","name_ar":"\u0627\u0644\u0633\u062a\u0631\u0629 \u0627\u0646\u062e\u0641\u0627\u0636 \u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell decline pullover"],"muscle":"chest","equipment":"barbell","aliases":["barbell decline pullover"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie down on a decline bench with your head lower than your hips and your feet secured.\nHold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.\nExtend your arms above your chest, keeping a slight bend in your elbows.\nLower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.\nPause for a moment, then return the barbell to the starting position by reversing the motion.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0646\u062d\u062f\u0631 \u0648\u0631\u0623\u0633\u0643 \u0623\u0642\u0644 \u0645\u0646 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0624\u0645\u0646\u062a\u0627\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0645\u0646\u0628\u0637\u062d\u0629 (\u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0645\u062a\u062c\u0647\u0629 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643) \u0648\u064a\u062f\u064a\u0643 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u0628\u0627\u0631 \u0628\u062d\u0631\u0643\u0629 \u0642\u0648\u0633\u064a\u0629 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062