623\u0645\u064a\u0646 \u0642\u062f\u0645\u064a\u0643.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0648\u0627\u0633\u0639\u0629 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u0633\u064a\u0637\u0631 \u0639\u0644\u064a\u0647\u0627\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0037","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["triceps","chest"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0037-Hj4FOCd.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0037-Hj4FOCd.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d2e13604-0dcf-5876-8e9f-4e9f93fc6719","source_id":"0038","name_en":"barbell drag curl","name_ar":"\u062a\u062c\u0639\u064a\u062f \u0633\u062d\u0628 \u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell drag curl"],"muscle":"biceps","equipment":"barbell","aliases":["barbell drag curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.\nLet the barbell hang at arm''s length in front of your thighs.\nKeeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.\nPause for a moment at the top, then slowly lower the barbell back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u062f\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u064a\u062a\u062f\u0644\u0649 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0630\u0631\u0627\u0639 \u0623\u0645\u0627\u0645 \u0641\u062e\u0630\u064a\u0643.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0627\u0631\u0641\u0639\u064a \u0627\u0644\u062d\u062f\u064a\u062f \u0644\u0623\u0639\u0644\u0649 \u0628\u0627\u062a\u062c\u0627\u0647 \u0635\u062f\u0631\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0634\u062f \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0038","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0038-IENzBdA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0038-IENzBdA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"418a361a-a8d9-55e1-8d36-1d1a934786a8","source_id":"1370","name_en":"barbell floor calf raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0639\u062c\u0644 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0628\u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell floor calf raise"],"muscle":"calves","equipment":"barbell","aliases":["barbell floor calf raise"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Place a barbell on the floor in front of you.\nStand with the balls of your feet on the edge of the barbell, with your heels hanging off.\nHold onto a stable object for balance if needed.\nRaise your heels as high as possible, using your calves to lift your body.\nPause for a moment at the top, then slowly lower your heels back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643.\n\u0642\u0641 \u0645\u0639 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u062d\u062f\u064a\u062f\u060c \u0645\u0639 \u062a\u0639\u0644\u064a\u0642 \u0643\u0639\u0628\u064a\u0643.\n\u062a\u0645\u0633\u0643 \u0628\u062c\u0633\u0645 \u062b\u0627\u0628\u062a \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646 \u0625\u0630\u0627 \u0644\u0632\u0645 \u0627\u0644\u0623\u0645\u0631.\n\u0627\u0631\u0641\u0639\u064a \u0643\u0639\u0628\u064a\u0643 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646\u060c \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0633\u0627\u0642\u064a\u0643 \u0644\u0631\u0641\u0639 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1370","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1370-2IHEa2T.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1370-2IHEa2T.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2c3677ac-2702-52a3-82a5-9d5ac5e6d5a3","source_id":"0039","name_en":"barbell front chest squat","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u0635\u062f\u0631\u064a \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0628\u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell front chest squat"],"muscle":"glutes","equipment":"barbell","aliases":["barbell front chest squat"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart, toes slightly turned out.\nHold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.\nEngage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.\nLower until your thighs are parallel to the ground, or as low as you can comfortably go.\nPause for a moment at the bottom, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0635\u0627\u0628\u0639 \u0627\u0644\u0642\u062f\u0645 \u0645\u0631\u0641\u0648\u0639\u0629 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u062a\u062c\u0647\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0644\u0623\u0639\u0644\u0649 \u0623\u062b\u0646\u0627\u0621 \u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u060c \u0623\u0648 \u0645\u0646\u062e\u0641\u0636\u064b\u0627 \u0628\u0642\u062f\u0631 \u0645\u0627 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"