2f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0628\u0645\u062c\u0631\u062f \u0648\u0635\u0648\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0627\u0646\u0641\u062c\u0631 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0627\u0644\u0642\u0641\u0632 \u0645\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0641\u0632\u060c \u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0643\u0627\u062d\u0644\u064a\u0646\u060c \u0648\u062f\u0641\u0639 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643.\n\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0648\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0644\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0053","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"202