\u0634\u0643\u0644 \u062c\u0633\u0645\u0643 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0625\u0644\u0649 \u0643\u062a\u0641\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0058","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0058-SNFfUff.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0058-SNFfUff.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6f06cc90-dd01-5aba-80aa-1bfb3444d823","source_id":"0059","name_en":"barbell lying preacher curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u0648\u0627\u0639\u0638 \u0627\u0644\u0643\u0630\u0628","match_names":["barbell lying preacher curl"],"muscle":"biceps","equipment":"barbell","aliases":["barbell lying preacher curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.\nKeeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\nContinue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the barbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0648\u0627\u0639\u0638 \u0645\u0639 \u0648\u0636\u0639 \u0635\u062f\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0641\u0629\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u0628\u0627\u0631 \u0639\u0646\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0059","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0059-SYJ4Bkt.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0059-SYJ4Bkt.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1bbd39de-9aae-5db4-8760-1ba3805c57e8","source_id":"0061","name_en":"barbell lying triceps extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0628\u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell lying triceps extension"],"muscle":"triceps","equipment":"barbell","a